import ast,hashlib,json,importlib.util
from pathlib import Path
p=Path('/workspace'); specs=json.loads((p/'proposal.json').read_text())['variants']
parent=ast.parse((p/'history_g0_r0021_bin_conditional.py').read_text())
pc=next(n for n in parent.body if isinstance(n,ast.ClassDef)); pm={n.name:n for n in pc.body if isinstance(n,ast.FunctionDef)}
for variant in specs:
 path=p/variant['file']; src=path.read_text(); mod=ast.parse(src)
 c=next(n for n in mod.body if isinstance(n,ast.ClassDef)); methods={n.name:n for n in c.body if isinstance(n,ast.FunctionDef)}
 assert len(methods)==len([n for n in c.body if isinstance(n,ast.FunctionDef)])
 for name,n in pm.items():
  nn=methods[{'forward':'_conditional_forward','diagnostics':'_conditional_diagnostics'}.get(name,name)]
  if name=='__init__':
   assert ast.dump(ast.Module(body=nn.body[:len(n.body)],type_ignores=[]))==ast.dump(ast.Module(body=n.body,type_ignores=[]))
  else:
   # Renaming the inherited public methods preserves their bodies.
   assert ast.dump(ast.Module(body=n.body,type_ignores=[]))==ast.dump(ast.Module(body=nn.body,type_ignores=[])),name
 for n in ast.walk(mod):
  if isinstance(n,(ast.Import,ast.ImportFrom)):
   names=[a.name.split('.')[0] for a in n.names] if isinstance(n,ast.Import) else [n.module.split('.')[0]]
   assert set(names)<={'torch','math'},names
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in {'open','eval','exec','__import__'}
 diag=methods['diagnostics']; keys=[]
 for n in ast.walk(diag):
  if isinstance(n,ast.Dict): keys += [k.value for k in n.keys if isinstance(k,ast.Constant) and isinstance(k.value,str)]
 print(variant['file'], 'sha256',hashlib.sha256(src.encode()).hexdigest(), 'all inherited method bodies/prefix preserved', 'diagnostic_literal_keys',len(set(keys)))
assert all(ast.dump(next(n for n in ast.parse((p/v['file']).read_text()).body if isinstance(n,ast.ClassDef)))==ast.dump(next(n for n in ast.parse((p/specs[0]['file']).read_text()).body if isinstance(n,ast.ClassDef))) for v in specs)
print('All variant class ASTs identical. torch_available:',importlib.util.find_spec('torch') is not None)
for f in ['baseline_reference.py','history_g0_r0016_oldest_bound.py','history_g1_r0016_exchangeable_joint.py','history_g0_r0021_bin_conditional.py']:
 print('Ancestor hash',f,hashlib.sha256((p/f).read_bytes()).hexdigest())
PY
sed -n '1,90p' /workspace/history_g0_r0016_oldest_bound.py; sed -n '300,420p' /workspace/history_g0_r0016_oldest_bound.py"

